                        assistantMessageId: options.assistantMessageId,
                        delta: "",
                        done: false,
                        kind: "tool_call",
                        input: call.input,
                        toolCallId: call.id,
                        toolName: call.name,
                    });
                    options.onStreamToolCall?.(call);
                    break;
                }
                case "finish":
                    finishReason = event.finishReason;
                    usage = event.usage;
                    providerMetadata = event.providerMetadata;
